int numIslands(vector<vector<char>>& g) {
    int R = g.size(), C = R ? g[0].size() : 0, cnt = 0;
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c) {
            if (g[r][c] != '1') continue;
            ++cnt;
            queue<pair<int, int>> q;
            q.push({r, c});
            g[r][c] = '0';  // mark on push
            while (!q.empty()) {
                auto [y, x] = q.front(); q.pop();
                for (int k = 0; k < 4; ++k) {
                    int ny = y + dr[k], nx = x + dc[k];
                    if (ny < 0 || ny >= R || nx < 0 || nx >= C) continue;
                    if (g[ny][nx] != '1') continue;
                    g[ny][nx] = '0';
                    q.push({ny, nx});
                }
            }
        }
    return cnt;
}

