from collections import deque

def open_lock(deadends, target):
    dead = set(deadends)
    if "0000" in dead:
        return -1
    if target == "0000":
        return 0
    dist = {"0000": 0}
    q = deque(["0000"])
    while q:
        s = q.popleft()
        for i in range(4):
            d = int(s[i])
            for step in (1, -1):
                t = s[:i] + str((d + step) % 10) + s[i+1:]
                if t in dead or t in dist:
                    continue
                if t == target:
                    return dist[s] + 1
                dist[t] = dist[s] + 1
                q.append(t)
    return -1
